export const CODEX_CLIENT_NOTIFICATION_COVERAGE = Object.freeze([
  internal("initialized", "App-server bridge"),
]);

export function codexProtocolCoverageSnapshot() {
  const counts = Object.fromEntries([...CODEX_PROTOCOL_COVERAGE_STATES].map((state) => [state, 0]));
  for (const entry of CODEX_PROTOCOL_COVERAGE) counts[entry.state] += 1;
  return {
    baseline: CODEX_PROTOCOL_BASELINE,
    counts,
    total: CODEX_PROTOCOL_COVERAGE.length,
    entries: CODEX_PROTOCOL_COVERAGE.map((entry) => ({ ...entry })),
  };
}

export function codexServerRequestCoverageSnapshot() {
  const counts = Object.fromEntries([...CODEX_PROTOCOL_COVERAGE_STATES].map((state) => [state, 0]));
  for (const entry of CODEX_SERVER_REQUEST_COVERAGE) counts[entry.state] += 1;
  return {
    baseline: CODEX_PROTOCOL_BASELINE,
    counts,
    total: CODEX_SERVER_REQUEST_COVERAGE.length,
    entries: CODEX_SERVER_REQUEST_COVERAGE.map((entry) => ({ ...entry })),
  };
}

export function codexServerNotificationCoverageSnapshot() {
  return coverageSnapshot(CODEX_SERVER_NOTIFICATION_COVERAGE);
}

export function codexClientNotificationCoverageSnapshot() {
  return coverageSnapshot(CODEX_CLIENT_NOTIFICATION_COVERAGE);
}

function coverageSnapshot(entries) {
  const counts = Object.fromEntries([...CODEX_PROTOCOL_COVERAGE_STATES].map((state) => [state, 0]));
  for (const entry of entries) counts[entry.state] += 1;
  return {
    baseline: CODEX_PROTOCOL_BASELINE,
    counts,
    total: entries.length,
    entries: entries.map((entry_) => ({ ...entry_ })),
  };
}

function browser(method, surface, extra = {}) {
  return entry(method, "browser", surface, extra);
}

function internal(method, surface, extra = {}) {
  return entry(method, "internal", surface, extra);
}

function customEquivalent(method, surface, extra = {}) {
  return entry(method, "custom-equivalent", surface, extra);
}

function planned(method, surface, extra = {}) {
  return entry(method, "planned", surface, extra);
}

function deferred(method, surface, extra = {}) {
  return entry(method, "deferred", surface, extra);
}

function notApplicable(method, surface, extra = {}) {
  return entry(method, "not-applicable", surface, extra);
}

function entry(method, state, surface, extra) {
  return Object.freeze({
    method,
    state,
    surface,
    origin: state === "custom-equivalent" ? "wfl-compatible" : "codex-native",
    ...extra,
  });
}
